        /// <returns>Task of ApiResponse (SecuresaleResponse)</returns>
        System.Threading.Tasks.Task<ApiResponse<SecuresaleResponse>> ApiCardsApiKeySecuresalePostWithHttpInfoAsync (string apiKey, SecuresaleFields basicData = default(SecuresaleFields), CancellationToken cancellationToken = default(CancellationToken));
